const LEARNED_STREAK=3,LEARNED_ACCURACY=.8,MIN_REVIEWS=3,DECAY_DAYS=14;const PV_PARTICLES=new Set(['up','down','off','out','in','on','over','away','back','through','along','around','into','for','about','after','with','to','at','of','from','across','by','apart','ahead','forward','onto','upon','towards']);function heuristicCategory(word){const w=String(word||'').trim().split(/\s+/).filter(Boolean);if(w.length<=1)return 'Vocabulary';if(w.length<=3&&w.slice(1).every(p=>PV_PARTICLES.has(p)))return 'Phrasal Verb';return 'Idiom'}function stateFor(word){const s=progress[word]||{reviews:0,status:'unseen',correct:0,wrong:0,streak:0,lastDate:null,nextReview:null,manualLearned:false,ease:2.5,reps:0,interval:0,skills:{},consecutiveCorrect:0,consecutiveWrong:0};if(s.status!=='learned'||!s.lastDate)return s;const last=new Date(s.lastDate).getTime();return isNaN(last)||Date.now()-last<=DECAY_DAYS*86400000?s:{...s,status:'weak'}}
