async function api(action,p,extra={}){let r;try{r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseUrl:p.baseUrl,apiKey:p.apiKey,apiUser:p.apiUser,action,...extra})})}catch(e){throw Error('Could not reach the AI service ('+((e&&e.message)||'network error')+'). Check your internet connection and try again.')}let j=null;try{j=await r.json()}catch(_){}if(!r.ok){const msg=(j&&(j.error||j.message))||('HTTP '+r.status);const det=(j&&j.detail)?String(j.detail).replace(/\s+/g,' ').trim():'';throw Error(msg+(det?' \u2014 '+det.slice(0,260):''))}if(!j)throw Error('AI request failed: empty or non-JSON response');return j}
