function renderList(){const q=(document.getElementById('search')?.value||'').toLowerCase(),statusFilter=document.getElementById('listStatus')?.value||'all',catFilter=document.getElementById('listCategory')?.value||'all',sort=document.getElementById('listSort')?.value||'newest';let added=words.slice(baseCount).map((d,i)=>({d,i,s:stateFor(d.word)})).filter(x=>!q||x.d.word.toLowerCase().includes(q));if(statusFilter!=='all')added=added.filter(x=>x.s.status===statusFilter);if(catFilter!=='all')added=added.filter(x=>(x.d.category||'Vocabulary')===catFilter);const sorters={newest:(a,b)=>(b.d.createdAt||0)-(a.d.createdAt||0),az:(a,b)=>a.d.word.localeCompare(b.d.word),weakest:(a,b)=>(a.s.correct/(a.s.reviews||1))-(b.s.correct/(b.s.reviews||1))||(b.s.wrong||0)-(a.s.wrong||0),status:(a,b)=>['weak','unseen','learned'].indexOf(a.s.status)-['weak','unseen','learned'].indexOf(b.s.status)};added.sort(sorters[sort]||sorters.newest);document.getElementById('wordList').innerHTML=added.length?added.map(({d,i})=>{const status=stateFor(d.word).status,cls=status==='learned'?'learned':status==='weak'?'weak':'unseen';return '<div class="wordItem" onclick="idx='+(baseCount+i)+';go(\'dashboard\');render()"><b>'+esc(d.word)+'</b><small>'+esc(d.meaning||'')+' · '+esc(d.category||'Vocabulary')+'</small><span class="ws ws-'+cls+'">'+(cls==='learned'?'LEARNED':cls==='weak'?'WEAK':'NOT READY')+'</span><button class="itemDel" title="Delete word" onclick="event.stopPropagation();deleteWordById('+(baseCount+i)+')">✕</button></div>'}).join(''):'<div class="empty">No user-added words match. Use “+ Add Word with AI”.</div>'}
function renderFlashGrid(){const q=(document.getElementById('flashSearch')?.value||'').toLowerCase();const all=words.filter(d=>!q||d.word.toLowerCase().includes(q));document.getElementById('flashGrid').innerHTML=all.length?all.map((d,i)=>{const status=stateFor(d.word).status,cls=status==='learned'?'learned':status==='weak'?'weak':'unseen';return '<div class="wordItem" onclick="idx='+words.indexOf(d)+';go(\'dashboard\');render()"><b>'+esc(d.word)+'</b><small>'+esc(d.meaning||'')+' · '+esc(d.category||'Vocabulary')+'</small>'+(d.generatedImage?'<span style="display:block;margin-top:4px;font-size:11px;color:#13994e">🖼 image ready</span>':'<span style="display:block;margin-top:4px;font-size:11px;color:#687080">⋯ image pending</span>')+'<span class="ws ws-'+cls+'">'+(cls==='learned'?'LEARNED':cls==='weak'?'WEAK':'NOT READY')+'</span><button class="itemDel" title="Delete word" onclick="event.stopPropagation();deleteWordById('+words.indexOf(d)+')">✕</button></div>'}).join(''):'<div class="empty">No flashcards yet. Use “+ Add Word with AI”.</div>'}
function quizPool(){return words.filter(d=>{if(quizCat!=='all'&&(d.category||'Vocabulary')!==quizCat)return false;if(quizStatus!=='all'&&stateFor(d.word).status!==quizStatus)return false;return true})}function quizLabel(){const c=quizCat==='all'?'All Categories':quizCat;const s=quizStatus==='all'?'All Statuses':({learned:'Remember',weak:'Not Remember',unseen:'Not Seen'}[quizStatus]||quizStatus);return c+' · '+s}function updateQuizCount(){const n=quizPool().length;const el=document.getElementById('quizPoolCount');if(el)el.textContent=n+' word'+(n===1?'':'s')+' match';const btn=document.getElementById('quizStartBtn');if(btn)btn.disabled=!n}function syncQuizChips(){document.querySelectorAll('#quizCatRow .dashCatChip').forEach(el=>el.classList.toggle('active',el.dataset.cat===quizCat));document.querySelectorAll('#quizStatusRow .dashStatusChip').forEach(el=>el.classList.toggle('active',el.dataset.status===quizStatus));updateQuizCount()}function toggleQuizCat(cat){quizCat=quizCat===cat?'all':cat;syncQuizChips()}function toggleQuizStatus(st){quizStatus=quizStatus===st?'all':st;syncQuizChips()}function resetQuizFilters(){quizCat='all';quizStatus='all';syncQuizChips()}function startQuiz(mode){quiz.mode=mode;let pool;if(mode==='due'){pool=dueWords().filter(d=>quizCat==='all'||(d.category||'Vocabulary')===quizCat)}else if(mode==='mistakes'){pool=words.filter(d=>mistakeActive(String(d.word||'').toLowerCase()))}else if(mode==='confuse'){pool=words.filter(d=>Array.isArray(d.confuse)&&d.confuse.some(x=>x&&x.word&&x.meaning))}else if(mode==='today'){pool=buildStudySession(20)}else if(mode&&mode.indexOf('skill:')===0){const t=mode.slice(6);pool=words.filter(function(w){const sk=stateFor(w.word).skills||{};return sk[t]!=null&&sk[t]<0.5}).sort(function(a,b){return getWordPriority(b)-getWordPriority(a)})}else{if(mode==='weak')quizStatus='weak';if(mode==='learned')quizStatus='learned';syncQuizChips();pool=quizPool()}quiz.items=[...pool].sort(()=>Math.random()-.5);quiz.pos=0;quiz.correct=0;quiz.total=0;quiz.answered=false;quiz.currentOptions=[];quiz.startTime=Date.now();quiz.sessionStreak=0;quiz.sessionMaxStreak=0;quiz.wrongWords=[];quiz.requeued={};quiz._done=false;quiz.pal=quiz.items.map(function(){return undefined});document.getElementById('quizModeLabel').textContent=quiz.mode==='due'?'Due Today':quiz.mode==='today'?'Today\'s Session — Top '+quiz.items.length:quiz.mode.indexOf('skill:')===0?'Weak-skill drill · '+(SKILL_LABELS[quiz.mode.slice(6)]||quiz.mode.slice(6)):quizLabel();if(!quiz.items.length){document.getElementById('quizEmpty').style.display='block';renderSmartEmpty();document.getElementById('quizQuestionWrap').style.display='none';document.getElementById('quizSessionBar').style.display='none';document.getElementById('quizSummaryWrap').style.display='none';document.getElementById('quizCounter').textContent='0 questions';return}document.getElementById('quizEmpty').style.display='none';document.getElementById('quizSummaryWrap').style.display='none';document.getElementById('quizQuestionWrap').style.display='block';document.getElementById('quizSessionBar').style.display='flex';if(quiz._timerInterval)clearInterval(quiz._timerInterval);quiz._timerInterval=setInterval(updateTimer,1000);updateTimer();showQuizQuestion()}
function genMeaningQ(d){const correct=d.meaning||'';return{type:'Meaning Match',q:'What does "'+d.word+'" mean?',correct,opts:getDistractors(correct,d.word,'meaning',d.confuse)};}
function genSynonymQ(d){const syns=d.syn||[];if(!syns.length)return genMeaningQ(d);const correct=syns[0];return{type:'Synonym',q:'Which word is closest in meaning to "'+d.word+'"?',correct,opts:getDistractors(correct,d.word,'syn',d.confuse)};}
function genAntonymQ(d){const ants=d.ant||[];if(!ants.length)return genMeaningQ(d);const correct=ants[0];return{type:'Antonym',q:'Which word is the opposite of "'+d.word+'"?',correct,opts:getDistractors(correct,d.word,'ant',d.confuse)};}
function genClozeQ(d){const ex=d.example||'';if(!ex)return genMeaningQ(d);const re=new RegExp('\\b'+d.word+'\\b','i');const blank=ex.replace(re,'______');if(blank===ex)return genMeaningQ(d);return{type:'Cloze Deletion',q:'Fill in the blank:<br><i>"'+blank+'"</i>',correct:d.word,opts:getDistractors(d.word,d.word,'word',d.confuse)};}
function genSentenceQ(d){const templates=['Choose the option that best completes: "The witness gave a ____ account of events."','Complete the sentence: "Her ____ knowledge impressed the examiner."','Choose the word that fits: "The minister made a ____ statement about the policy."'];const tpl=templates[quiz.pos%templates.length];return{type:'Sentence Completion',q:tpl,correct:d.word,opts:getDistractors(d.word,d.word,'word',d.confuse)};}
const TYPE_KEY={'Meaning Match':'meaning','Synonym':'synonym','Antonym':'antonym','Cloze Deletion':'cloze','Sentence Completion':'sentence','Confusion Drill':'confuse','flashcard':'flashcard','practice':'practice'};const SKILL_GEN={meaning:genMeaningQ,synonym:genSynonymQ,antonym:genAntonymQ,cloze:genClozeQ,sentence:genSentenceQ};const SKILL_LABELS={meaning:'Meaning Match',synonym:'Synonym',antonym:'Antonym',cloze:'Cloze Deletion',sentence:'Sentence Completion',confuse:'Confusion Drill',flashcard:'Flashcard recall',practice:'Dashboard practice'};function calculateNextReview(s,quality){quality=Math.max(0,Math.min(5,Math.round(quality)));if(quality<3){s.reps=0;s.interval=1;s.consecutiveCorrect=0;s.consecutiveWrong=(s.consecutiveWrong||0)+1}else{s.reps=(s.reps||0)+1;s.consecutiveWrong=0;s.consecutiveCorrect=(s.consecutiveCorrect||0)+1;s.interval=s.reps===1?1:s.reps===2?6:Math.round(Math.max(1,s.interval||1)*(s.ease||2.5))}s.ease=Math.max(1.3,(s.ease||2.5)+(0.1-(5-quality)*(0.08+(5-quality)*0.02)));s.nextReview=new Date(Date.now()+s.interval*86400000).toISOString()}function recordReview(opts){const wordKey=opts.wordKey;const quality=Math.max(0,Math.min(5,Math.round(opts.quality||0)));const correct=quality>=3;const s=stateFor(wordKey);s.reviews=(s.reviews||0)+1;s.lastDate=new Date().toDateString();if(correct){s.correct=(s.correct||0)+1;s.streak=(s.streak||0)+1}else{s.wrong=(s.wrong||0)+1;s.streak=0;s.manualLearned=false}if(opts.manual&&correct)s.manualLearned=true;const key=TYPE_KEY[opts.questionType]||opts.questionType||'flashcard';s.skills=s.skills||{};s.skills[key]=(s.skills[key]==null?0.5:s.skills[key])*0.7+(correct?1:0)*0.3;calculateNextReview(s,quality);if(opts.manual&&correct){s.interval=Math.max(s.interval||1,3);s.nextReview=new Date(Date.now()+s.interval*86400000).toISOString()}const acc=s.reviews?s.correct/s.reviews:0;s.status=(s.manualLearned||(s.reviews>=MIN_REVIEWS&&s.streak>=LEARNED_STREAK&&acc>=LEARNED_ACCURACY))?'learned':'weak';progress[wordKey]=s;mistakeRecord(wordKey,correct);dailyRecord(correct);quizHistory.push({word:wordKey,type:key,correct:correct,answer:opts.answer!=null?String(opts.answer):'',responseMs:opts.responseMs||0,time:new Date().toLocaleDateString()+' '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});if(quizHistory.length>200)quizHistory=quizHistory.slice(-200);localStorage.setItem('sscQuizHistory',JSON.stringify(quizHistory));save();updateProgress();updateQuizCount()}function getWordPriority(word){const s=stateFor(typeof word==='string'?word:word.word);const overdue=s.nextReview?Math.max(0,(Date.now()-new Date(s.nextReview).getTime())/86400000):0;const sk=Object.values(s.skills||{});const weakness=sk.length?1-Math.min.apply(null,sk):0;const isNew=(s.reviews||0)===0?1:0;return overdue*10+weakness*40+(s.consecutiveWrong||0)*15+isNew*15-((s.consecutiveCorrect||0)>=4?10:0)}function chooseQuestionType(word){const s=stateFor(typeof word==='string'?word:word.word);const entries=Object.entries(s.skills||{});const weakest=entries.length?entries.slice().sort(function(a,b){return a[1]-b[1]})[0][0]:null;if(weakest&&SKILL_GEN[weakest]&&Math.random()<0.7)return SKILL_GEN[weakest];const gens=[genMeaningQ,genSynonymQ,genAntonymQ,genClozeQ,genSentenceQ];return gens[Math.floor(Math.random()*gens.length)]}function buildStudySession(n){return words.slice().sort(function(a,b){return getWordPriority(b)-getWordPriority(a)}).slice(0,n||20)}function renderSkillDiag(){const wrap=document.getElementById('pgSkillDiag');if(!wrap)return;const agg={};words.forEach(function(w){const sk=(stateFor(w.word).skills||{});Object.keys(sk).forEach(function(k){(agg[k]=agg[k]||[]).push(sk[k])})});const rows=Object.keys(agg).map(function(k){const arr=agg[k];return{k:k,avg:arr.reduce(function(a,b){return a+b},0)/arr.length,n:arr.length}}).filter(function(r){return r.avg<0.85}).sort(function(a,b){return a.avg-b.avg}).slice(0,3);if(!rows.length){wrap.style.display='none';return}wrap.style.display='block';document.getElementById('pgSkillDiagList').innerHTML=rows.map(function(r){return '<div class="pgQuizRow"><div class="pgQuizDot '+(r.avg<0.5?'fail':'ok')+'"></div><div class="pgQuizRowWord">'+esc(SKILL_LABELS[r.k]||r.k)+'</div><div class="pgQuizRowResult">'+Math.round(r.avg*100)+'% avg · '+r.n+' word'+(r.n===1?'':'s')+' tracked</div><div class="pgQuizRowTime"><button class="btn" style="padding:3px 10px;font-size:11px" onclick="startQuiz(\'skill:'+r.k+'\');go(\'quiz\')">Drill</button></div></div>'}).join('')}/* ---------- MOCK TEST (TCS CBT layout) ---------- */
const MOCK_TOTAL=25,MOCK_SECS=1200,MOCK_POS=2,MOCK_NEG=0.5;
let mock={phase:'intro',items:[],cur:0,sel:{},marked:{},visited:{},qms:{},last:0,endAt:0,timer:null,warned:false,lastResult:null};
let mockHistory=(function(){try{return JSON.parse(localStorage.getItem('sscMockResults')||'[]')}catch(e){return[]}})();
function mockSaveHist(){try{localStorage.setItem('sscMockResults',JSON.stringify(mockHistory.slice(0,20)))}catch(e){}}
function mockFmt(sec){sec=Math.max(0,Math.round(sec));const m=Math.floor(sec/60),ss=sec%60;return (m<10?'0':'')+m+':'+(ss<10?'0':'')+ss}
function mockShuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function genBuiltinQ(d){if(!d.q||!Array.isArray(d.opts)||d.opts.length!==4||!Number.isInteger(d.ans)||d.ans<0||d.ans>3)return null;const correct=d.opts[d.ans];if(correct==null)return null;return{type:'Exam MCQ',q:d.q,correct:correct,opts:mockShuffle(d.opts.slice()).map(function(l,ix){return{label:l,originalIndex:ix}})}}
function buildMockPaper(){const pool=mockShuffle(words.filter(function(w){return w&&w.word&&(w.meaning||w.q)}));if(!pool.length)return[];const cands=[];pool.forEach(function(w,pi){const gs=[genMeaningQ,genBuiltinQ];if((w.syn||[]).length)gs.push(genSynonymQ);if((w.ant||[]).length)gs.push(genAntonymQ);if(d_())gs.push(genClozeQ);function d_(){try{return w.example&&(new RegExp('\\b'+w.word+'\\b','i')).test(w.example)}catch(e){return false}}gs.forEach(function(g,gi){cands.push({w:w,g:g,gi:gi+pi})})});mockShuffle(cands);const items=[];const seen={};for(const c of cands){if(items.length>=MOCK_TOTAL)break;let q=null;try{q=c.g(c.w)}catch(e){q=null}if(!q||!q.correct||!Array.isArray(q.opts)||q.opts.length<2)continue;const sig=c.w.word+'|'+q.q;if(seen[sig])continue;seen[sig]=1;items.push({word:c.w.word,type:q.type,q:q.q,correct:q.correct,opts:q.opts,src:c.w})}return items}
/* === Test Zone: unified AI Quiz + Mock === */
let tzTab='quiz';let quizSessions=(function(){try{return JSON.parse(localStorage.getItem('sscQuizSessions')||'[]')}catch(e){return[]}})();
function quizModeName(m){if(!m)return'Practice';if(m==='due')return'Due Today';if(m==='today')return"Today's Session";if(m==='filtered')return'Custom filters';if(m==='mistakes')return'Mistakes drill';if(m==='confuse')return'Confusion drill';if(m==='weak')return'Weak words';if(m==='learned')return'Remember drill';if(m.indexOf('skill:')===0)return'Skill drill · '+(SKILL_LABELS[m.slice(6)]||m.slice(6));return m}
function quizSessionSave(){if(!(quiz.total>0))return;try{quizSessions.unshift({date:new Date().toLocaleString(),ts:Date.now(),mode:quiz.mode,asked:quiz.total,correct:quiz.correct,pct:Math.round(quiz.correct*100/quiz.total),timeUsed:quiz.startTime?Math.round((Date.now()-quiz.startTime)/1000):0});quizSessions=quizSessions.slice(0,20);localStorage.setItem('sscQuizSessions',JSON.stringify(quizSessions))}catch(e){}}
function renderMockStats(){const el=document.getElementById('mockBest');if(el)el.textContent=mockHistory.length?Math.max.apply(null,mockHistory.map(function(r){return r.pct||0}))+'%':'—'}
function renderTzRecent(){const el=document.getElementById('tzRecent');if(!el)return;const rows=[];(quizSessions||[]).forEach(function(s){rows.push({ts:s.ts||0,kind:'quiz',date:s.date,label:quizModeName(s.mode)+' · '+s.asked+'Q',score:s.correct+' / '+s.asked,pct:s.pct,meta:s.timeUsed?mockFmt(s.timeUsed):''})});(mockHistory||[]).forEach(function(r){rows.push({ts:r.ts||(Date.parse(r.date)||0),kind:'mock',date:r.date,label:'SSC CGL · '+r.total+'Q',score:r.score+' / '+r.max,pct:r.pct,meta:r.timeUsed?mockFmt(r.timeUsed):''})});rows.sort(function(a,b){return b.ts-a.ts});const top=rows.slice(0,6);el.innerHTML='<div class="tzRecentHead"><b>📋 Recent results</b><span class="muted">'+(rows.length?'AI Quiz + Mock, newest first':'No attempts yet — both quiz and mock results land here')+'</span></div>'+(top.length?top.map(function(r){return '<div class="tzRow"><span class="tzBadge '+r.kind+'">'+(r.kind==='quiz'?'⚡ Quiz':'🎯 Mock')+'</span><span class="tzLabel">'+esc(r.label)+'</span><b>'+r.score+'</b><span class="mkBadge '+(r.pct>=60?'g':'n')+'">'+r.pct+'%</span>'+(r.meta?'<span class="muted">⏱ '+r.meta+'</span>':'')+'<span class="tzDate">'+esc(r.date)+'</span></div>'}).join(''):'<div class="muted" style="font-size:12px;padding:2px 0 4px">Start an AI Quiz session or a Mock Test to build your result history.</div>')}
function tzShow(t){tzTab=t;const q=document.getElementById('tzQuiz'),m=document.getElementById('tzMock');if(q)q.style.display=t==='quiz'?'block':'none';if(m)m.style.display=t==='mock'?'block':'none';const bq=document.getElementById('tzTabQuiz'),bm=document.getElementById('tzTabMock');if(bq)bq.classList.toggle('active',t==='quiz');if(bm)bm.classList.toggle('active',t==='mock');const tr=document.getElementById('tzRecent');if(tr)tr.style.display=(t==='mock'&&mock.phase==='exam')?'none':'block'}
function tzSwitch(t){if(tzTab===t){window.scrollTo(0,0);return}tzShow(t);if(t==='quiz'){syncQuizChips();renderQuizStats();updateMistakeCount();if(!quiz.answered&&quiz.items.length===0){renderSmartEmpty();quizResumeInject()}}else{renderMockPage()}window.scrollTo(0,0)}
function tzGoMockIntro(){tzShow('mock');if(mock.phase!=='exam'){mock.phase='intro'}renderMockPage();window.scrollTo(0,0)}
function renderTestZone(){renderTzRecent();renderMockStats();if(tzTab==='quiz'){tzShow('quiz');syncQuizChips();renderQuizStats();updateMistakeCount();if(!quiz.answered&&quiz.items.length===0){renderSmartEmpty();quizResumeInject()}}else{tzShow('mock');renderMockPage()}}
function renderMockPage(){const ex=document.getElementById('mkExam'),intro=document.getElementById('mkIntro'),res=document.getElementById('mkResult');if(!ex)return;tzShow('mock');intro.style.display=mock.phase==='intro'?'block':'none';ex.style.display=mock.phase==='exam'?'block':'none';res.style.display=mock.phase==='result'?'block':'none';if(mock.phase==='intro')renderMockIntro();else if(mock.phase==='exam')mockRenderQ();else if(mock.phase==='result'&&mock.lastResult)renderMockResult(mock.lastResult)}
function renderMockIntro(){const el=document.getElementById('mkIntro');if(!el)return;const pool=words.filter(function(w){return w&&w.word&&(w.meaning||w.q)});let hist='';el.innerHTML='<div class="card mkIntroCard"><h2>Mock Test — SSC CGL Pattern (English)</h2><div class="mkInstStats"><span><b>'+MOCK_TOTAL+'</b> questions</span><span><b>'+(MOCK_SECS/60)+' min</b></span><span><b>+'+MOCK_POS+'</b> correct</span><span><b>−'+MOCK_NEG+'</b> wrong</span><span><b>'+MOCK_TOTAL*2+'</b> max marks</span></div><h3>Instructions</h3><ul class="mkInst"><li>The paper is generated fresh from <b>your word bank</b> ('+pool.length+' words available) — meaning, synonym, antonym, cloze and exam-pattern MCQs.</li><li>The timer runs continuously for '+(MOCK_SECS/60)+' minutes and the paper <b>auto-submits at 00:00</b>. A red warning appears in the last 5 minutes.</li><li>Use the palette to jump between questions: <span class="mkLegendSq" style="background:#43a047"></span>Answered &nbsp;<span class="mkLegendSq" style="background:#e53935"></span>Not answered &nbsp;<span class="mkLegendSq" style="background:#7b1fa2"></span>Marked for review &nbsp;<span class="mkLegendSq" style="background:#90a4ae"></span>Not visited.</li><li>You can change any answer before submitting. Mock scores do <b>not</b> affect your SRS schedule.</li><li>Very small word banks may produce a shorter paper; marks scale to the actual paper length.</li></ul>'+(pool.length?'<button class="btn primary" style="padding:11px 22px" onclick="startMock()">I am ready to begin</button> <button class="btn" style="padding:11px 22px" onclick="tzSwitch(\'quiz\')">⚡ Warm up in AI Quiz</button>':'<p class="muted">Add some words first (use <b>+ Add Word with AI</b> on the Dashboard), then take the mock.</p>')+hist+'</div>'}
function startMock(){const items=buildMockPaper();if(!items.length){alert('No words available to build a paper. Add words first.');return}if(mock.timer){clearInterval(mock.timer);mock.timer=null}mock.phase='exam';mock.items=items;mock.cur=0;mock.sel={};mock.marked={};mock.visited={0:1};mock.qms={};mock.last=Date.now();mock.endAt=Date.now()+MOCK_SECS*1000;mock.warned=false;mock.lastResult=null;const wEl=document.getElementById('mkWarn');if(wEl)wEl.style.display='none';const tEl=document.getElementById('mkTimer');if(tEl)tEl.classList.remove('warn');renderMockPage();mockTick();mock.timer=setInterval(mockTick,500);window.scrollTo(0,0)}
function mockCounts(){let an=0,na=0,pu=0,nv=0;mock.items.forEach(function(_,i){if(mock.marked[i]){pu++;if(mock.sel[i]!=null)an++}else if(mock.sel[i]!=null)an++;else if(mock.visited[i])na++;else nv++});return{an:an,na:na,pu:pu,nv:nv}}
function mockFlushQ(){const now=Date.now();mock.qms[mock.cur]=(mock.qms[mock.cur]||0)+(now-mock.last);mock.last=now}
function mockTick(){if(mock.phase!=='exam')return;const remain=(mock.endAt-Date.now())/1000;const tEl=document.getElementById('mkTimer'),wEl=document.getElementById('mkWarn');if(!tEl)return;tEl.textContent='Time Left '+mockFmt(remain);mockFlushQ();const qEl=document.getElementById('mkQClock');if(qEl)qEl.textContent='⏱ '+mockFmt((mock.qms[mock.cur]||0)/1000);if(remain<=300&&!mock.warned){mock.warned=true;tEl.classList.add('warn');if(wEl)wEl.style.display='block'}if(mock.warned&&wEl)wEl.textContent='⚠ Last '+Math.ceil(remain/60)+' Minutes — the paper auto-submits at 00:00';if(remain<=0)mockFinish(true)}
function mockRenderQ(){const it=mock.items[mock.cur];if(!it)return;mock.visited[mock.cur]=1;document.getElementById('mkQNum').textContent='Question: '+(mock.cur+1);document.getElementById('mkQType').textContent=it.type+' · from "'+it.word+'"';document.getElementById('mkQText').innerHTML=it.q;const sel=mock.sel[mock.cur];document.getElementById('mkOpts').innerHTML=it.opts.map(function(o,ix){return '<div class="mkOpt'+(sel===o.label?' sel':'')+'" onclick="mockPick('+ix+')"><span class="mkOptDot"></span><span>'+esc(o.label)+'</span></div>'}).join('');mockRenderPalette();const qEl=document.getElementById('mkQClock');if(qEl)qEl.textContent='⏱ '+mockFmt((mock.qms[mock.cur]||0)/1000)}
function mockRenderPalette(){const c=mockCounts();document.getElementById('mkPalGrid').innerHTML=mock.items.map(function(_,i){let cls='nv';if(mock.marked[i])cls='pu';else if(mock.sel[i]!=null)cls='an';else if(mock.visited[i])cls='na';const tick=(mock.marked[i]&&mock.sel[i]!=null)?' ✓':'';return '<button class="mkPalBtn '+cls+(i===mock.cur?' cur':'')+'" onclick="mockJump('+i+')">'+(i+1)+tick+'</button>'}).join('');document.getElementById('mkPalCount').textContent='Attempted '+Object.keys(mock.sel).length+' / '+mock.items.length;document.getElementById('mkPalLegend').innerHTML='<div class="mkLegendRow"><span><span class="mkLegendSq" style="background:#43a047"></span>Answered</span><b>'+c.an+'</b></div><div class="mkLegendRow"><span><span class="mkLegendSq" style="background:#e53935"></span>Not Answered</span><b>'+c.na+'</b></div><div class="mkLegendRow"><span><span class="mkLegendSq" style="background:#7b1fa2"></span>Marked for Review</span><b>'+c.pu+'</b></div><div class="mkLegendRow"><span><span class="mkLegendSq" style="background:#90a4ae"></span>Not Visited</span><b>'+c.nv+'</b></div>'}
function mockPick(ix){const it=mock.items[mock.cur];if(!it)return;const o=it.opts[ix];if(!o||o.label==null)return;mock.sel[mock.cur]=o.label;mockRenderQ()}
function mockClearResp(){delete mock.sel[mock.cur];mockRenderQ()}
function mockMarkToggle(){if(mock.marked[mock.cur])delete mock.marked[mock.cur];else mock.marked[mock.cur]=1;mockRenderQ()}
function mockJump(i){if(i<0||i>=mock.items.length)return;mockFlushQ();mock.cur=i;mockRenderQ();window.scrollTo(0,0)}
function mockNav(d){mockJump(mock.cur+d)}
function mkModal(title,bodyHtml,btns){document.getElementById('mkModalTitle').textContent=title;document.getElementById('mkModalBody').innerHTML=bodyHtml;document.getElementById('mkModalBtns').innerHTML=btns;document.getElementById('mkModal').style.display='flex'}
function mkModalClose(){document.getElementById('mkModal').style.display='none'}
function mockSubmitAsk(){const c=mockCounts();mkModal('Submit test?','<table><tr><td>Answered</td><td style="text-align:right"><b style="color:#2e7d32">'+c.an+'</b></td></tr><tr><td>Not answered</td><td style="text-align:right"><b style="color:#c62828">'+c.na+'</b></td></tr><tr><td>Marked for review</td><td style="text-align:right"><b style="color:#7b1fa2">'+c.pu+'</b></td></tr><tr><td>Not visited</td><td style="text-align:right"><b>'+c.nv+'</b></td></tr></table>'+(c.an<mock.items.length?'<p class="muted" style="font-size:13px">You still have unanswered questions.</p>':''),'<button class="btn" onclick="mkModalClose()">Continue test</button><button class="btn dangerBtn" onclick="mkModalClose();mockFinish(false)">Yes, submit</button>')}
function mockExitAsk(){mkModal('Exit the test?','<p>Your progress in this attempt will be discarded and nothing will be scored.</p>','<button class="btn" onclick="mkModalClose()">Keep giving the test</button><button class="btn dangerBtn" onclick="mkModalClose();mockAbort()">Exit</button>')}
function mockAbort(){if(mock.timer){clearInterval(mock.timer);mock.timer=null}mock.phase='intro';mock.lastResult=null;renderMockPage()}
function mockFinish(auto){if(mock.phase!=='exam')return;mockFlushQ();if(mock.timer){clearInterval(mock.timer);mock.timer=null}let correct=0,wrong=0,skip=0;mock.items.forEach(function(it,i){if(mock.sel[i]==null)skip++;else if(mock.sel[i]===it.correct)correct++;else wrong++});const score=correct*MOCK_POS-wrong*MOCK_NEG;const max=mock.items.length*MOCK_POS;const attempted=correct+wrong;const rec={date:new Date().toLocaleString(),ts:Date.now(),score:score,max:max,correct:correct,wrong:wrong,skip:skip,attempted:attempted,total:mock.items.length,pct:attempted?Math.round(correct/attempted*100):0,timeUsed:Math.round((MOCK_SECS*1000-(mock.endAt-Date.now()))/1000),auto:!!auto,items:mock.items.map(function(it,i){return{q:it.q,type:it.type,word:it.word,correct:it.correct,yours:mock.sel[i]!=null?mock.sel[i]:null,opts:it.opts.map(function(o){return o.label}),secs:Math.round((mock.qms[i]||0)/1000),meaning:it.src.meaning||'',syn:(it.src.syn||[]).join(', '),ant:(it.src.ant||[]).join(', ')}})};mockHistory.unshift(rec);mockSaveHist();mock.lastResult=rec;mock.phase='result';renderMockPage();renderTzRecent();renderMockStats();window.scrollTo(0,0)}
function renderMockResult(r){const el=document.getElementById('mkResult');if(!el)return;let rows=r.items.map(function(it,i){const good=it.yours===it.correct;let verdict=it.yours==null?'<span class="mkBadge n">Skipped · 0</span>':(good?'<span class="mkBadge g">Correct · +2</span>':'<span class="mkBadge r">Wrong · −0.5</span>');const opts=it.opts.map(function(l){let cls='',tag='';if(l===it.correct){cls=' good';if(l===it.yours)tag=' <b style="color:#2e7d32">✓ Your answer — correct</b>';else tag=' <b style="color:#2e7d32">✓ Correct answer</b>'}else if(l===it.yours){cls=' bad';tag=' <b style="color:#c62828">✗ Your answer</b>'}return '<div class="mkRevOpt'+cls+'">'+esc(l)+tag+'</div>'}).join('');const ex=[];if(it.meaning)ex.push('Meaning: '+esc(it.meaning));if(it.syn)ex.push('Synonyms: '+esc(it.syn));if(it.ant)ex.push('Antonyms: '+esc(it.ant));return '<div class="mkRevRow"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>Q'+(i+1)+' · '+esc(it.type)+'</b><span class="muted">⏱ '+it.secs+'s</span></div><div class="mkQText" style="padding:9px 0">'+it.q+'</div>'+opts+'<div style="margin-top:7px">'+verdict+' <span class="muted">from "'+esc(it.word)+'"</span></div>'+(ex.length?'<details style="margin-top:7px"><summary class="muted" style="cursor:pointer">Explanation</summary><p class="muted" style="margin:7px 0 0">'+ex.join(' · ')+'</p></details>':'')+'</div>'}).join('');el.innerHTML='<div class="card" style="max-width:860px;margin:0 auto 14px"><h2>Mock Test Result'+(r.auto?' — auto-submitted at 00:00':'')+'</h2><div class="mkScoreRow"><div><div class="mkScoreBig">'+r.score+' <small style="font-size:18px;color:#7882a3">/ '+r.max+'</small></div><div class="muted">Total marks</div></div><div class="mkScoreStats"><div><b>'+r.correct+'</b><small>Correct</small></div><div><b>'+r.wrong+'</b><small>Wrong</small></div><div><b>'+r.skip+'</b><small>Skipped</small></div><div><b>'+r.pct+'%</b><small>Accuracy</small></div><div><b>'+mockFmt(r.timeUsed)+'</b><small>Time used</small></div></div></div></div><div style="max-width:860px;margin:0 auto 20px;display:flex;gap:10px;flex-wrap:wrap"><button class="btn primary" onclick="startMock()">Retake — new paper</button><button class="btn" onclick="tzSwitch(\'quiz\')">⚡ Drill words in AI Quiz</button><button class="btn" onclick="mockAbort()">Back to Mock overview</button></div><h3 style="max-width:860px;margin:8px auto">Question-by-question review</h3>'+rows}
document.addEventListener('keydown',function(e){const pg=document.querySelector('.page.active');if(!pg||pg.id!=='mock'||mock.phase!=='exam')return;if(document.getElementById('mkModal').style.display==='flex')return;if(e.key>='1'&&e.key<='4'){mockPick(parseInt(e.key,10)-1);e.preventDefault()}else if(e.key==='Enter'){mockNav(1);e.preventDefault()}});

function getDistractors(correct,sourceWord,field,confuse){const pool=words.filter(w=>w.word!==sourceWord);const distractors=[];const seen=new Set();seen.add(correct.toLowerCase());const confSeed=(confuse||[]).map(function(c){return field==='meaning'?(c&&c.meaning):(c&&c.word)}).filter(function(v){return v&&!seen.has(String(v).toLowerCase())});for(const cv of confSeed){if(distractors.length>=3)break;if(sourceWord&&String(cv).toLowerCase()===String(sourceWord).toLowerCase())continue;distractors.push(cv);seen.add(String(cv).toLowerCase())}for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}for(const w of pool){let val;if(field==='meaning')val=w.meaning;else if(field==='syn')val=(w.syn||[])[0];else if(field==='ant')val=(w.ant||[])[0];else val=w.word;if(val&&!seen.has(val.toLowerCase())){distractors.push(val);seen.add(val.toLowerCase());if(distractors.length>=3)break;}}while(distractors.length<3){const fb=['None of the above','Not applicable','Cannot be determined'];for(const f of fb)if(!seen.has(f.toLowerCase())){distractors.push(f);seen.add(f.toLowerCase());if(distractors.length>=3)break;}if(distractors.length>=3)break;}const opts=[correct,...distractors.slice(0,3)];for(let i=opts.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[opts[i],opts[j]]=[opts[j],opts[i]];}return opts.map((label,originalIndex)=>({label,originalIndex}));}
function genQuizQ(d){const gens=[genMeaningQ,genSynonymQ,genAntonymQ,genClozeQ,genSentenceQ];return gens[Math.floor(Math.random()*gens.length)](d);}
function showQuizQuestion(){const d=quiz.items[quiz.pos];quiz.answered=false;quiz.qShownAt=Date.now();quizSnapSave();document.getElementById('quizCounter').textContent=(quiz.pos+1)+' / '+quiz.items.length;document.getElementById('qzQNum').textContent='Question: '+(quiz.pos+1);quizPalName();quizRenderPal();const qData=quiz.mode==='confuse'?genConfuseQ(d):(quiz.mode==='today'?chooseQuestionType(d)(d):(quiz.mode&&quiz.mode.indexOf('skill:')===0?SKILL_GEN[quiz.mode.slice(6)](d):genQuizQ(d)));quiz.currentQData=qData;quiz.currentOptions=qData.opts;document.getElementById('qzTypeLabel').textContent=qData.type;document.getElementById('quizQuestion').innerHTML=qData.q;document.getElementById('quizOptions').innerHTML=quiz.currentOptions.map((o,di)=>'<button class="quizOption mkOpt" onclick="answerQuiz('+di+')"><span class="mkOptDot"></span><span>'+esc(o.label)+'</span></button>').join('');document.getElementById('quizFeedback').className='quizFeedback';document.getElementById('quizFeedback').innerHTML='';var qn=document.getElementById('quizNext');qn.disabled=true;qn.textContent='Save & Next';document.getElementById('quizStatus').textContent='Choose the option you believe is correct.'}
function answerQuiz(displayIndex){if(quiz.answered)return;const d=quiz.items[quiz.pos],selected=quiz.currentOptions[displayIndex];if(!selected)return;const isCorrect=selected.label===quiz.currentQData.correct;quiz.answered=true;quiz.total++;quiz.pal[quiz.pos]=isCorrect?'an':'na';if(isCorrect){quiz.correct++;quiz.sessionStreak++;quiz.sessionMaxStreak=Math.max(quiz.sessionMaxStreak,quiz.sessionStreak)}else{quiz.sessionStreak=0;quiz.wrongWords.push({word:d.word,meaning:d.meaning||''})}const correctIdx=quiz.currentOptions.findIndex(o=>o.label===quiz.currentQData.correct);document.querySelectorAll('.quizOption').forEach((b,i)=>{b.disabled=true;if(i===correctIdx)b.classList.add('correct');if(i===displayIndex&&!isCorrect)b.classList.add('wrong')});const fb=document.getElementById('quizFeedback');fb.className='quizFeedback show '+(isCorrect?'good':'bad');let fbHtml=isCorrect?'<b>✓ Correct!</b><br>':'<b>✗ Wrong.</b> Correct answer: <b>'+esc(quiz.currentQData.correct)+'</b><br>'+(d.meaning||'')+'<br>';const responseMs=Date.now()-(quiz.qShownAt||Date.now());recordReview({wordKey:d.word,questionType:quiz.currentQData.type,quality:isCorrect?(responseMs<3000?5:4):1,responseMs:responseMs,answer:quiz.currentQData.correct,manual:isCorrect});const st=stateFor(d.word);fbHtml+=isCorrect?'<b>Status: Remember</b> — stays until a wrong answer.':'<b>Status: Not Remember</b> — it will come back sooner.';fbHtml+=memoryHooksHtml(d)+'<br><button class="qzReviewBtn" onclick="go(\'dashboard\');idx=words.findIndex(w=>w.word===\''+esc(d.word)+'\');render()">Open flashcard</button>';fb.innerHTML=fbHtml;if(!isCorrect){quiz.requeued=quiz.requeued||{};const rk=String(d.word).toLowerCase();if((quiz.requeued[rk]||0)<2){quiz.requeued[rk]=(quiz.requeued[rk]||0)+1;const qk=Math.min(quiz.items.length,quiz.pos+4);quiz.items.splice(qk,0,d);quiz.pal=quizPalShift(quiz.pal,qk)}}document.getElementById('quizStatus').innerHTML=st.status==='learned'?'<span class="badge learn">LEARNED</span>':'<span class="badge weak">WEAK</span>';document.getElementById('quizNext').disabled=false;document.getElementById('quizNext').textContent=quiz.pos===quiz.items.length-1?'Save & Finish':'Save & Next';quizRenderPal();updateSessionBar();renderQuizStats();quizSnapSave()}
function nextQuiz(){if(quiz.pos<quiz.items.length-1){quiz.pos++;showQuizQuestion()}else{quizEndNow()}}
function quizPalShift(old,k){const src=old||[],np=[];for(let i=0;i<=src.length;i++){np[i]=i<k?src[i]:(i===k?undefined:src[i-1])}return np}
function quizPalName(){const el=document.getElementById('qzPalName');if(el)el.textContent=(quizModeName(quiz.mode)||'AI Quiz').toUpperCase()}
function quizRenderPal(){const grid=document.getElementById('qzPalGrid');if(!grid||!quiz.items.length)return;const pal=quiz.pal||[];let an=0,na=0;grid.innerHTML=quiz.items.map(function(_,i){let c=pal[i];if(c==='an')an++;else if(c==='na')na++;else c='nv';return '<span class="mkPalBtn qzPal '+c+(i===quiz.pos?' cur':'')+'">'+(i+1)+'</span>'}).join('');const cnt=document.getElementById('qzPalCount');if(cnt)cnt.textContent='Answered '+(an+na)+' / '+quiz.items.length;const lg=document.getElementById('qzPalLegend');if(lg)lg.innerHTML='<div class="mkLegendRow"><span><span class="mkLegendSq" style="background:#43a047"></span>Correct</span><b>'+an+'</b></div><div class="mkLegendRow"><span><span class="mkLegendSq" style="background:#e53935"></span>Wrong</span><b>'+na+'</b></div><div class="mkLegendRow"><span><span class="mkLegendSq" style="background:#90a4ae"></span>Not visited</span><b>'+(quiz.items.length-an-na)+'</b></div>'}
function quizEndAsk(){if(quiz._done||!quiz.items.length)return;const n=quiz.total;const msg=n?'End this session? '+n+' question'+(n===1?'':'s')+' answered — it will be saved to Recent results.':'End this session? Nothing answered yet — nothing will be saved.';if(confirm(msg))quizEndNow()}
function quizEndNow(){if(quiz._timerInterval){clearInterval(quiz._timerInterval);quiz._timerInterval=null}quizSessionSave();quiz._done=true;try{localStorage.removeItem('sscQuizSession')}catch(e){}document.getElementById('quizQuestionWrap').style.display='none';document.getElementById('quizSessionBar').style.display='none';document.getElementById('quizCounter').textContent='Complete';const qe=document.getElementById('quizEmpty');if(!quiz.total){qe.style.display='block';renderSmartEmpty();renderTzRecent();return}const pc=Math.round(quiz.correct*100/quiz.total);const rm=quiz.mode;qe.style.display='block';qe.innerHTML='<div class="qzDone"><b>Session complete — '+quiz.correct+' / '+quiz.total+' correct ('+pc+'%)</b><small>Saved to Recent results at the top of the Test Zone.</small><div class="qzDoneBtns"><button class="btn" onclick="startQuiz(\''+rm+'\')">🔄 Same drill again</button><button class="btn primary" onclick="tzGoMockIntro()">🎯 Ready? Take the Mock Test</button></div></div>';renderTzRecent()}
function renderQuizStats(){updateProgress();const total=Object.values(progress).reduce((a,s)=>a+(s.correct||0)+(s.wrong||0),0),correct=Object.values(progress).reduce((a,s)=>a+(s.correct||0),0);document.getElementById('quizAccuracy').textContent=total?Math.round(correct*100/total)+'%':'—'}
function updateTimer(){if(!quiz.startTime)return;const elapsed=Math.floor((Date.now()-quiz.startTime)/1000);const mins=Math.floor(elapsed/60);const secs=elapsed%60;const el=document.getElementById('qzTimer');if(el)el.textContent=mins+':'+(secs<10?'0':'')+secs;const e2=Math.floor((Date.now()-(quiz.qShownAt||Date.now()))/1000);const qc=document.getElementById('qzQClock');if(qc)qc.textContent='\u23f1 '+Math.floor(e2/60)+':'+('0'+e2%60).slice(-2);}
function updateSessionBar(){const el1=document.getElementById('qzStreak');const el2=document.getElementById('qzAcc');if(el1)el1.textContent='🔥 '+quiz.sessionStreak+' in a row';if(el2)el2.textContent=quiz.total?Math.round(quiz.correct/quiz.total*100)+'% accuracy':'—';}
/* === Quiz session resume === */
function quizSnapSave(){try{if(!quiz.items.length||quiz._done){localStorage.removeItem('sscQuizSession');return}let sp=quiz.pos;if(quiz.answered){if(quiz.pos>=quiz.items.length-1){localStorage.removeItem('sscQuizSession');return}sp=quiz.pos+1}localStorage.setItem('sscQuizSession',JSON.stringify({mode:quiz.mode,label:(document.getElementById('quizModeLabel')||{}).textContent||'',pos:sp,total:quiz.total,correct:quiz.correct,sessionStreak:quiz.sessionStreak,sessionMaxStreak:quiz.sessionMaxStreak,wrongWords:quiz.wrongWords||[],requeued:quiz.requeued||{},startTime:quiz.startTime||Date.now(),savedAt:Date.now(),items:quiz.items.slice(0,120),pal:(quiz.pal||[]).slice(0,120)}))}catch(e){}}
function quizSnapRead(){try{const s=JSON.parse(localStorage.getItem('sscQuizSession')||'null');if(!s||!Array.isArray(s.items)||!s.items.length||s.pos==null||s.pos>=s.items.length)return null;return s}catch(e){return null}}
function quizResumeInject(){const el=document.getElementById('quizEmpty');if(!el)return;const s=quizSnapRead();if(!s)return;if(quiz.items.length&&!quiz._done)return;const mins=Math.max(1,Math.round((Date.now()-(s.savedAt||Date.now()))/60000));const ago=mins<60?mins+' min ago':Math.floor(mins/60)+'h '+(mins%60)+'m ago';el.insertAdjacentHTML('afterbegin','<div class="qzResume"><div class="qzResumeInfo"><b>\ud83d\udcd3 Continue where you left off</b><small>'+esc(s.label||quizModeName(s.mode))+' · Question '+(s.pos+1)+' of '+s.items.length+' · '+s.correct+' correct · saved '+ago+'</small></div><div class="qzResumeBtns"><button class="btn primary" onclick="quizResume()">\u25b6 Resume</button><button class="btn" onclick="quizResumeDiscard()">\u2715 Discard</button></div></div>')}
function quizResume(){const s=quizSnapRead();if(!s)return;quiz.mode=s.mode;quiz.items=s.items;quiz.pos=Math.min(s.pos,s.items.length-1);quiz.correct=s.correct||0;quiz.total=s.total||0;quiz.sessionStreak=s.sessionStreak||0;quiz.sessionMaxStreak=s.sessionMaxStreak||0;quiz.wrongWords=s.wrongWords||[];quiz.requeued=s.requeued||{};quiz.pal=(s.pal||[]).slice(0,quiz.items.length);while(quiz.pal.length<quiz.items.length)quiz.pal.push(undefined);quiz.startTime=s.startTime||Date.now();quiz.answered=false;quiz.currentOptions=[];quiz.currentQData=null;quiz._done=false;const qe=document.getElementById('quizEmpty');if(qe){qe.style.display='none';qe.innerHTML=''}document.getElementById('quizQuestionWrap').style.display='block';document.getElementById('quizSessionBar').style.display='flex';document.getElementById('quizModeLabel').textContent=s.label||quizModeName(s.mode);if(quiz._timerInterval)clearInterval(quiz._timerInterval);quiz._timerInterval=setInterval(updateTimer,1000);updateTimer();updateSessionBar();showQuizQuestion();window.scrollTo(0,0)}
function quizResumeDiscard(){try{localStorage.removeItem('sscQuizSession')}catch(e){}renderSmartEmpty()}
function renderSmartEmpty(){const poolNow=quizPool();const scoped=words.filter(w=>quizCat==='all'||(w.category||'Vocabulary')===quizCat);const weakCount=scoped.filter(w=>stateFor(w.word).status==='weak').length;const dueCount=dueWords().filter(w=>quizCat==='all'||(w.category||'Vocabulary')===quizCat).length;const totalCount=scoped.length;let html='';if(!poolNow.length){if(!words.length){html+='<h3>No words yet</h3><div class="empty">Use “+ Add Word with AI” to build your first quiz.</div>'}else{html+='<h3>No words match the selected filters</h3><div class="empty">Pick another category/status combination or reset the filters.</div><div style="text-align:center;margin:12px 0"><button class="btn primary" onclick="resetQuizFilters()">Reset filters</button></div>'}}else{html+='<h3>Ready to quiz?</h3>'}if(weakCount>0)html+='<div class="qzSmartCard" onclick="startQuiz(\'weak\')"><div class="qzSmartIcon">🔴</div><div class="qzSmartInfo"><b>'+weakCount+' weak word'+(weakCount===1?'':'s')+' waiting</b><small>Focus on words you got wrong</small></div><div class="qzSmartArrow">›</div></div>';if(dueCount>0)html+='<div class="qzSmartCard" onclick="startQuiz(\'due\')"><div class="qzSmartIcon">📅</div><div class="qzSmartInfo"><b>'+dueCount+' word'+(dueCount===1?'':'s')+' due today</b><small>SRS says it is time to review these</small></div><div class="qzSmartArrow">›</div></div>';if(totalCount>=1)html+='<div class="qzSmartCard" onclick="resetQuizFilters();startQuiz(\'all\')"><div class="qzSmartIcon">🎯</div><div class="qzSmartInfo"><b>Quiz '+totalCount+' word'+(totalCount===1?'':'s')+(quizCat==='all'?'':' in '+esc(quizCat))+'</b><small>Random mix from the selected category</small></div><div class="qzSmartArrow">›</div></div>';document.getElementById('quizEmpty').innerHTML=html;}
document.addEventListener('keydown',function(e){var tzq=document.getElementById('tzQuiz');if(!document.getElementById('mock').classList.contains('active')||!tzq||tzq.style.display==='none')return;if(document.getElementById('quizQuestionWrap').style.display==='none'&&document.getElementById('quizSummaryWrap').style.display==='none')return;if(!quiz.answered&&document.getElementById('quizQuestionWrap').style.display!=='none'){if(e.key>='1'&&e.key<='4'){const idx=parseInt(e.key)-1;if(idx<quiz.currentOptions.length)answerQuiz(idx);e.preventDefault()}}else if(quiz.answered){if(e.key==='Enter'||e.key===' '){nextQuiz();e.preventDefault()}}if(e.key==='Escape'){quizEndAsk();e.preventDefault()}});
function openProvider(type='text'){document.getElementById('providerModal').classList.add('show');document.getElementById('pType').value=type;toggleImageFields();document.getElementById('providerStatus').textContent=''}function closeProvider(){document.getElementById('providerModal').classList.remove('show')}function toggleImageFields(){document.getElementById('imageSizeField').style.display=document.getElementById('pType').value==='image'?'block':'none'}
async function testProvider(){const p={baseUrl:document.getElementById('pBase').value.trim(),apiKey:document.getElementById('pKey').value.trim(),apiUser:document.getElementById('pUser').value.trim(),model:document.getElementById('pModel').value.trim(),type:document.getElementById('pType').value,size:document.getElementById('pSize').value},s=document.getElementById('providerStatus');if(!p.baseUrl||!p.apiKey)return s.textContent='Base URL and API key are required.';s.textContent='Testing...';try{if(p.type==='image')await api('image',p,{model:p.model,prompt:'A simple educational icon for an English vocabulary flashcard: a book and lightbulb, no text.',size:p.size});else await api('chat',p,{model:p.model,messages:[{role:'user',content:'Reply with OK only.'}]});s.textContent='Connection successful.'}catch(e){s.textContent='Test failed: '+e.message}}
function saveProvider(){const p={id:crypto.randomUUID(),name:document.getElementById('pName').value.trim()||'Unnamed Provider',type:document.getElementById('pType').value,baseUrl:document.getElementById('pBase').value.trim().replace(/\/$/,''),model:document.getElementById('pModel').value.trim(),apiUser:document.getElementById('pUser').value.trim(),apiKey:document.getElementById('pKey').value.trim(),size:document.getElementById('pSize').value,active:false};if(!p.baseUrl||!p.apiKey||!p.model){document.getElementById('providerStatus').textContent='Name, Base URL, Model and API key are required.';return}if(!providers.some(x=>x.type===p.type))p.active=true;providers.push(p);save();renderProviders();closeProvider();toast('Provider saved')}
function setActive(id){const p=providers.find(x=>x.id===id);if(!p)return;providers.filter(x=>x.type===p.type).forEach(x=>x.active=false);p.active=true;save();renderProviders();toast('Active '+p.type+' provider changed')}
function removeProvider(id){providers=providers.filter(x=>x.id!==id);save();renderProviders()}
function providerHtml(type){const arr=providers.filter(p=>p.type===type);return arr.length?arr.map(p=>'<div class="provider"><div class="providerHead"><b>'+esc(p.name)+'</b><span class="muted">'+(p.active?'ACTIVE':'')+'</span></div><div class="muted">Default model: '+esc(p.model)+' · '+esc(p.baseUrl)+'</div><div style="margin-top:10px"><button class="btn" onclick="setActive(\''+p.id+'\')">Use This</button> <button class="btn" onclick="removeProvider(\''+p.id+'\')">Remove</button></div></div>').join(''):'<div class="empty">No '+type+' provider configured.</div>'}
function renderProviders(){document.getElementById('textProviders').innerHTML=providerHtml('text');document.getElementById('imageProviders').innerHTML=providerHtml('image')}
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',1800)}

/* ===== Supabase Cloud Sync ===== */
let sbClient=null,sbUser=null,sbSyncTimer=null,sbLastSync=0;
const SB_SCHEMA=`CREATE TABLE IF NOT EXISTS sb_words(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,word text NOT NULL,json_data jsonb NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(user_id,word));
CREATE TABLE IF NOT EXISTS sb_providers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,json_data jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sb_progress(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,word_key text NOT NULL,json_data jsonb NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(user_id,word_key));
CREATE TABLE IF NOT EXISTS sb_quiz_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,json_data jsonb NOT NULL,created_at timestamptz DEFAULT now());
ALTER TABLE sb_words ENABLE ROW LEVEL SECURITY;ALTER TABLE sb_providers ENABLE ROW LEVEL SECURITY;ALTER TABLE sb_progress ENABLE ROW LEVEL SECURITY;ALTER TABLE sb_quiz_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users can manage own words" ON sb_words FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own providers" ON sb_providers FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own progress" ON sb_progress FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own quiz_history" ON sb_quiz_history FOR ALL USING (auth.uid() = user_id);`;
function initSupabase(){const url='https://nzjiyyfydxflivtwceix.supabase.co',key='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im56aml5eWZ5ZHhmbGl2dHdjZWl4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODg0NTgyODIsImV4cCI6MjEwNDAzNDI4Mn0.1KnrLH2RZvtV308RZ483cCJBNLzTBmW0ZXqzDMj1jlY';if(window.supabase){sbClient=window.supabase.createClient(url,key);return true}return false}
function renderAuthPanel(){const el=document.getElementById('authPanel');if(!el)return;if(sbUser){const name=sbUser.email?sbUser.email.split('@')[0]:'User';el.innerHTML='<div class="authPanelInner"><div class="authAvatar">'+name.charAt(0).toUpperCase()+'</div><div class="authTitle" style="color:#13bd60">Signed In</div><div class="authSubtitle">'+esc(sbUser.email||'')+'</div><div class="syncBadge '+(sbLastSync?'synced':'offline')+'">'+(sbLastSync?'● Synced '+timeAgo(sbLastSync):'○ Not synced yet')+'</div><button class="authBtn authLogout" onclick="sbLogout()">Sign Out</button></div>'}else{el.innerHTML='<div class="authPanelInner"><div class="authAvatar">☁️</div><div class="authTitle">Cloud Sync</div><div class="authSubtitle">Sync across devices</div><button class="authBtn authPrimary" onclick="openAuthModal()">Sign In / Sign Up</button></div>'}}
function timeAgo(ts){const d=Date.now()-ts,m=Math.floor(d/60000);if(m<1)return 'just now';if(m<60)return m+'m ago';return Math.floor(m/60)+'h ago'}
function openAuthModal(){document.getElementById('authModal').classList.add('show');document.getElementById('authModalEmail').value='';document.getElementById('authModalPass').value='';document.getElementById('authModalError').textContent='';document.getElementById('authModalTitle').textContent='Sign In';document.getElementById('authModalSubtitle').textContent='Sign in to sync your progress';document.getElementById('authSignUpFields').style.display='none';document.getElementById('authModalSwitchBtn').textContent="Don't have an account? Sign Up";authIsSignUp=false}
function closeAuthModal(){document.getElementById('authModal').classList.remove('show')}
let authIsSignUp=false;
function authToggleView(){authIsSignUp=!authIsSignUp;document.getElementById('authModalTitle').textContent=authIsSignUp?'Create Account':'Sign In';document.getElementById('authModalSubtitle').textContent=authIsSignUp?'Create a free account to sync across devices':'Sign in to sync your progress';document.getElementById('authSignUpFields').style.display=authIsSignUp?'block':'none';document.getElementById('authModalSwitchBtn').textContent=authIsSignUp?'Already have an account? Sign In':"Don't have an account? Sign Up";document.getElementById('authModalError').textContent=''}
async function sbSignUp(){const email=document.getElementById('authModalEmail').value.trim();const pass=document.getElementById('authModalPass').value;const confirm=document.getElementById('authModalConfirm').value;const errEl=document.getElementById('authModalError');if(!email||!pass){if(errEl){errEl.style.color='#df4d68';errEl.textContent='Email and password are required.'}return}if(pass.length<6){if(errEl){errEl.style.color='#df4d68';errEl.textContent='Password must be at least 6 characters.'}return}if(pass!==confirm){if(errEl){errEl.style.color='#df4d68';errEl.textContent='Passwords do not match.'}return}if(!sbClient){if(errEl){errEl.style.color='#df4d68';errEl.textContent='Connection not ready.'}return}try{const{data,error}=await sbClient.auth.signUp({email,password:pass});if(error)throw error;if(data.session&&data.user){sbUser={id:data.user.id,email:data.user.email};localStorage.setItem('sbSession',JSON.stringify(sbUser));closeAuthModal();toast('Account created and signed in!');renderAuthPanel();await syncToCloud();renderAuthPanel()}else if(data.user){const{data:loginData,error:loginError}=await sbClient.auth.signInWithPassword({email,password:pass});if(loginError)throw loginError;sbUser={id:loginData.user.id,email:loginData.user.email};localStorage.setItem('sbSession',JSON.stringify(sbUser));closeAuthModal();toast('Account created and signed in!');renderAuthPanel();await syncToCloud();renderAuthPanel()}}catch(e){if(errEl){errEl.style.color='#df4d68';errEl.textContent=e.message||'Sign up failed.'}}}
async function sbLogin(){const email=document.getElementById('authModalEmail').value.trim();const pass=document.getElementById('authModalPass').value;const errEl=document.getElementById('authModalError');if(!email||!pass){if(errEl)errEl.textContent='Email and password are required.';return}if(!sbClient){if(errEl)errEl.textContent='Connection not ready.';return}try{const{data,error}=await sbClient.auth.signInWithPassword({email,password:pass});if(error)throw error;sbUser={id:data.user.id,email:data.user.email};localStorage.setItem('sbSession',JSON.stringify(sbUser));closeAuthModal();toast('Signed in!');renderAuthPanel();await syncFromCloud();renderAuthPanel()}catch(e){if(errEl){errEl.style.color='#df4d68';errEl.textContent=e.message||'Invalid email or password.'}}}
function sbLogout(){sbUser=null;localStorage.removeItem('sbSession');if(sbClient)sbClient.auth.signOut();renderAuthPanel();toast('Signed out (local data kept)')}
function scheduleSupabaseSync(){if(!sbUser||!sbClient)return;if(sbSyncTimer)clearTimeout(sbSyncTimer);sbSyncTimer=setTimeout(()=>syncToCloud().then(()=>renderAuthPanel()).catch(()=>{}),500)}
async function syncToCloud(){if(!sbUser||!sbClient)return;try{const uid=sbUser.id;await sbClient.from('sb_progress').upsert({user_id:uid,word_key:'__deleted_ssc__',json_data:[...hiddenSeed]},{onConflict:'user_id,word_key'}).catch(()=>{});const userWords=words.slice(baseCount);const wordUpserts=userWords.map(d=>({user_id:uid,word:d.word,json_data:{...d,generatedImage:undefined}}));if(wordUpserts.length){const batches=[];for(let i=0;i<wordUpserts.length;i+=50)batches.push(wordUpserts.slice(i,i+50));for(const batch of batches){await sbClient.from('sb_words').upsert(batch,{onConflict:'user_id,word'})}}await sbClient.from('sb_providers').delete().eq('user_id',uid);if(providers.length){const provUpserts=providers.map(p=>({user_id:uid,json_data:p}));await sbClient.from('sb_providers').upsert(provUpserts)}const progressEntries=Object.entries(progress).map(([k,v])=>({user_id:uid,word_key:k,json_data:v}));if(progressEntries.length){const batches=[];for(let i=0;i<progressEntries.length;i+=50)batches.push(progressEntries.slice(i,i+50));for(const batch of batches){await sbClient.from('sb_progress').upsert(batch,{onConflict:'user_id,word_key'})}}await sbClient.from('sb_quiz_history').delete().eq('user_id',uid);if(quizHistory.length){const histUpserts=quizHistory.map(h=>({user_id:uid,json_data:h}));await sbClient.from('sb_quiz_history').upsert(histUpserts)}sbLastSync=Date.now()}catch(e){console.error('Sync to cloud failed:',e)}}
async function syncFromCloud(){if(!sbUser||!sbClient)return;try{const uid=sbUser.id;const{data:wData}=await sbClient.from('sb_words').select('word,json_data').eq('user_id',uid);if(wData&&wData.length){const remoteWords=wData.map(r=>r.json_data);const localWords=loadWords();const localMap=new Map(localWords.map(w=>[w.word,w]));const mergedMap=new Map();remoteWords.forEach(w=>mergedMap.set(w.word,w));localWords.forEach(w=>{if(!mergedMap.has(w.word))mergedMap.set(w.word,w)});const filteredUserWords=[...mergedMap.values()].filter(w=>!hiddenSeed.has((w.word||w).toLowerCase()));localStorage.setItem('sscAIWords',JSON.stringify(filteredUserWords));words=[...seed.filter(s=>!hiddenSeed.has(s.word.toLowerCase())),...filteredUserWords];baseCount=words.length-loadWords().length}const{data:pData}=await sbClient.from('sb_providers').select('json_data').eq('user_id',uid);if(pData&&pData.length){providers=pData.map(r=>r.json_data);localStorage.setItem('sscAIProviders',JSON.stringify(providers))}const{data:prData}=await sbClient.from('sb_progress').select('word_key,json_data').eq('user_id',uid);if(prData&&prData.length){const remoteProgress={};prData.forEach(r=>remoteProgress[r.word_key]=r.json_data);const localProgress=JSON.parse(localStorage.getItem('sscProgress')||'{}');Object.keys(remoteProgress).forEach(k=>{if(!localProgress[k])localProgress[k]=remoteProgress[k]});progress=localProgress;localStorage.setItem('sscProgress',JSON.stringify(progress))}if(progress.__deleted_ssc__){progress.__deleted_ssc__.forEach(w=>hiddenSeed.add(String(w).toLowerCase()));delete progress.__deleted_ssc__}const{data:hData}=await sbClient.from('sb_quiz_history').select('json_data').eq('user_id',uid);if(hData&&hData.length){quizHistory=hData.map(r=>r.json_data);localStorage.setItem('sscQuizHistory',JSON.stringify(quizHistory))}sbLastSync=Date.now();render();renderList();updateProgress();renderProviders();renderQuizStats()}catch(e){console.error('Sync from cloud failed:',e)}}

document.getElementById('search')?.addEventListener('input',renderList);render();renderProviders();updateProgress();renderQuizStats();if(document.getElementById('quizEmpty'))renderSmartEmpty();const dueBtn=document.getElementById('dueBtn');if(dueBtn){dueBtn.textContent=dueToday?'Due Today':'Show All';dueBtn.classList.toggle('active',dueToday)}/* Auto-generate images for any words (seed + user-added) that don't have one yet, using the active Image AI provider. Runs in the background with throttling; does nothing if no image provider is configured. */
setTimeout(autoGenerateMissingImages,800);function sbRestoreSession(){try{const s=JSON.parse(localStorage.getItem('sbSession')||'null');if(s&&s.id&&s.email){sbUser=s;return true}}catch(e){}return false}try{initSupabase();sbClient.auth.getSession().then(({data:{session}})=>{if(session&&session.user){sbUser={id:session.user.id,email:session.user.email};localStorage.setItem('sbSession',JSON.stringify(sbUser));syncFromCloud().then(()=>renderAuthPanel()).catch(()=>renderAuthPanel())}else if(sbRestoreSession()&&sbClient){syncFromCloud().then(()=>renderAuthPanel()).catch(()=>renderAuthPanel())}else renderAuthPanel()}).catch(()=>{if(sbRestoreSession()&&sbClient){syncFromCloud().then(()=>renderAuthPanel()).catch(()=>renderAuthPanel())}else renderAuthPanel()})}catch(e){console.error('Supabase init error:',e)}
;function sbCollapsed(){return document.body.classList.contains('sbc')}
function sbSetCollapse(c){document.body.classList.toggle('sbc',c);try{localStorage.setItem('sscSidebar',c?'c':'o')}catch(e){}var b=document.getElementById('sbToggleBtn');if(b){b.textContent=c?'❯':'❮';b.setAttribute('aria-expanded',c?'false':'true')}}
function sbToggleCollapse(){sbSetCollapse(!sbCollapsed())}
function sbDrawer(open){document.body.classList.toggle('sbo',!!open)}
try{if(localStorage.getItem('sscSidebar')==='c')sbSetCollapse(true)}catch(e){}
window.addEventListener('resize',function(){if(window.innerWidth>1000)document.body.classList.remove('sbo')});
document.addEventListener('keydown',function(e){if(e.key==='Escape')sbDrawer(false)});
